('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Tham mưu các phương án phân bố vốn thực hiện/xử lý', '3', 'Tham mưu kế hoạch giải ngân nguồn vốn, phân khai nguồn vốn giải ngân của từng nhà thầu, từng hạng mục của các công trình/dự án', 'Bnar Kế hoạch giải ngân', NULL, NULL, 'one_time', NULL, NULL, '0'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Giải trình các nội dung liên quan khi có yêu cầu của cơ quan chức năng (nếu có);', '5', 'Liên hệ, phối hợp với Bộ, ngành ở Trung ương, Sở, ngành và các địa phương trong tỉnh để có các phương án tham mưu và đề xuất về công tác quản lý các nguồn vốn;', 'Các văn bản tham mưu đề xuất', NULL, NULL, 'one_time', NULL, NULL, '1'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Thực hiện các nhiệm vụ khác liên quan đến công tác kế hoạch, lập kế hoạch', '6', 'Thực hiện công tác báo cáo tình hình triển khai thực hiện công tác hàng tháng, cả năm của Ban QLDA và báo cáo theo yêu cầu của sở ngành chuyên môn thuộc lĩnh vực được giao', 'Tổng hợp báo cáo hàng tháng/ năm của Ban; các báo cáo theo yêu cầu', NULL, NULL, 'one_time', NULL, NULL, '2'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Chủ trì thẩm định, trình Giám đốc Ban QLDA phê duyệt Kế hoạch lựa chọn nhà thầu; quyết định chỉ định thầu', '12', 'Đăng tải thông tin trên hệ thống mạng đấu thầu quốc gia về Kế hoạch lựa chọn nhà thầu, thông báo mời thầu, kết quả đấu thầu và các thủ tục liên quan', 'Thông tin được đăng tải; Thông báo kết quả đấu thầu…', NULL, NULL, 'one_time', NULL, NULL, '3'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Chủ trì thẩm định, trình Giám đốc Ban QLDA phê duyệt Kế hoạch lựa chọn nhà thầu; quyết định chỉ định thầu', '12', 'Tham mưu Giám đốc, các Phó Giám đốc phụ trách xử lý tình huống trong đấu thầu; Giải quyết kiến nghị trong lựa chọn nhà thầu; hủy thầu theo quy định', 'Văn bản tham mưu', NULL, NULL, 'one_time', NULL, NULL, '4'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Chủ trì nghiên cứu Quy hoạch, kế hoạch, đề án, dự án, ý tưởng của các ngành, địa phương để tìm kiếm các cơ hội đầu tư', '15', 'Phối hợp với các sở, ban, ngành và các đơn vị, địa phương liên quan khảo sát, xác định và đề xuất danh mục đầu tư hàng năm và trung hạn', 'Danh mục đầu tư', NULL, NULL, 'one_time', NULL, NULL, '5'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Chủ trì nghiên cứu Quy hoạch, kế hoạch, đề án, dự án, ý tưởng của các ngành, địa phương để tìm kiếm các cơ hội đầu tư', '15', 'Chủ trì, tham mưu vận động, xúc tiến đầu tư các dự án ODA, xây dựng hồ sơ, tài liệu xúc tiến đầu tư, chuẩn bị đầu tư các dự án ODA;', 'Hồ sơ, tài liệu', NULL, NULL, 'one_time', NULL, NULL, '6'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Phiên dịch và biên dịch từ tiếng Anh sang tiếng Việt và ngược lại;', '17', 'Phối hợp với các phòng Quản lý dự án trong quá trình lập hồ sơ Báo cáo nghiên cứu tiền khả thi, Báo cáo đề xuất chủ trương đầu tư chương trình, dự án', 'Báo cáo đề xuất', NULL, NULL, 'one_time', NULL, NULL, '7'),
('2026', 'KHDT', 'Phòng Kế hoạch - Đấu thầu', 'Chủ trì, phối hợp với các phòng chuyên môn thực hiện nhiệm vụ giám sát đánh giá đầu tư', '18', 'Thực hiện công tác lập báo cáo tháng/quý/năm và đột xuất khi có yêu cầu về công tác đấu thầu, công tác thực hiện tổng thể các dự án/công trình/nguồn vốn, công tác thực hiện hợp đồng, tiến độ thực hiện các dự án…, đồng thời có trách nhiệm giải trình các nội dung liên quan khi có yêu cầu của cơ quan chức năng', 'Các báo cáo', NULL, NULL, 'one_time', NULL, NULL, '8'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Thẩm định điều chỉnh thiết kế, dự toán', '4', 'Thẩm định hồ sơ mời quan tâm/hồ sơ mời sơ tuyển/hồ sơ mời thầu/hồ sơ yêu cầu; kết quả đánh giá hồ sơ quan tâm/hồ sơ dự tuyển/ hồ sơ đề xuất/ kết quả lựa chọn nhà thầu', 'Văn bản thẩm định', NULL, NULL, 'one_time', NULL, NULL, '0'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Chủ trì rà soát, cập nhật các quy định của pháp luật về đầu tư xây dựng/quản lý đầu tư xây dựng,', '6', 'Kiểm tra, rà soát về trình tự thủ tục pháp lý, sự phù hợp của hồ sơ bước chuẩn bị dự án, hồ sơ thiết kế bản vẽ thi công và dự toán đối với các bước thực hiện trước đó trước khi trình cơ quan chuyên môn, quản lý thẩm định, phê duyệt', 'Báo cáo kết quả', NULL, NULL, 'one_time', NULL, NULL, '1'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Chủ trì rà soát, cập nhật các quy định của pháp luật về đầu tư xây dựng/quản lý đầu tư xây dựng,', '6', 'Kiểm tra chất lượng, tiến độ và việc đảm bảo các quy định trong tổ chức thi công xây dựng đối với các đơn vị, bộ phận triển khai dự án;', 'Biên bản kiểm tra', NULL, NULL, 'one_time', NULL, NULL, '2'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Kiểm tra, xác nhận các nội dung đề xuất điều chỉnh bổ sung trong quá tình thi công xây dựng', '7', 'Phối hợp bộ phận chủ trì trong công tác làm rõ hồ sơ mời thầu/hồ sơ dự thầu, giải quyết kiến nghị trong quá trình lựa chọn nhà thầu', 'Nội dung yêu cầu', NULL, NULL, 'one_time', NULL, NULL, '3'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Kiểm tra, xác nhận các nội dung đề xuất điều chỉnh bổ sung trong quá tình thi công xây dựng', '7', 'Thực hiện công tác báo cáo và trách nhiệm giải trình liên quan đến các nội dung, nhiệm vụ của Phòng hàng tuần, tháng/quý/năm và đột xuất', 'Các báo cáo', NULL, NULL, 'one_time', NULL, NULL, '4'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Kiểm tra, xác nhận các nội dung đề xuất điều chỉnh bổ sung trong quá tình thi công xây dựng', '7', 'Rà soát, cập nhật điều chỉnh chế độ chính sách phù hợp; nghiên cứu và áp dụng vào thực tế các sáng kiến kinh nghiệm trong quản lý', 'Báo cáo nội dung cập nhật; Các sáng kiến đề xuất áp dụng', NULL, NULL, 'one_time', NULL, NULL, '5'),
('2026', 'KTTD', 'Phòng Kỹ thuật - Thẩm định', 'Chủ trì xây dựng hệ thống các quy trình theo tiêu chuẩn ISO', '8', 'Nghiêm thu hoàn thành bàn giao đưa vào sử dụng các dự án do Ban QLDA thực hiện quản lý dự án và giao phòng chủ trì: dự án Trường Cao đẳng Y Hà Tĩnh; dự án Trung tâm sản nhi tại bệnh viện Đa khoa tỉnh Hà Tĩnh; dự án Cảo tạo Đài TH tỉnh…;', 'Hồ sơ nghiệm thu', NULL, NULL, 'one_time', NULL, NULL, '6'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Lập Báo cáo nghiên cứu tiền khả thi, Báo cáo đề xuất chủ trương đầu tư các dự án', '1', 'Tổ chức lập và trình thẩm định, phê  duyệt các hồ sơ: đề cương nhiệm vụ tư vấn xây dựng; Báo cáo nghiên cứu khả thi/Báo cáo kinh tế - kỹ thuật, Thiết kế kỹ thuật, thiết kế bản vẽ thi công, dự toán và thực hiện các công việc cần thiết khác có liên quan của các công trình/dự án', 'Hồ sơ trình thẩm định', NULL, NULL, 'one_time', NULL, NULL, '0'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Phối hợp với Phòng Kế hoạch - Đấu thầu xử lý các tình huống, kiến nghị trong đấu thầu', '5', 'Chủ trì, phối hợp với các phòng thương thảo hợp đồng, dự thảo hợp đồng và quản lý hợp đồng đối với các gói thầu thuộc dự án', 'Dự thảo hợp đồng', NULL, NULL, 'one_time', NULL, NULL, '1'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Phối hợp với Phòng Kế hoạch - Đấu thầu xử lý các tình huống, kiến nghị trong đấu thầu', '5', 'Thực hiện các nội dung liên quan trong công tác quản lý dự án (từ khâu lập Báo cáo đề xuất chủ trương đầu tư cho đến khi công trình hoàn thành, nghiệm thu và bàn giao đưa vào sử dụng, quyết toán vốn đầu tư', 'Báo cáo công việc liên quan;', NULL, NULL, 'one_time', NULL, NULL, '2'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Kiểm tra, đôn đốc về tiến độ, khối lượng, đơn giá, chất lượng, mỹ thuật/kiến trúc công trình', '6', 'Kiểm tra hồ sơ quản lý chất lượng, công tác an toàn lao động, vệ sinh môi trường và rà soát hồ sơ nghiệm thu khối lượng hoàn thành các giai đoạn/hạng mục/nghiệm thu giai đoạn hoàn thành bàn giao đưa vào sử dụng đến thanh/quyết toán công trình', 'Báo cáo kiểm tra/biên bản kiểm tra, Biên bản nghiệm thu; Hồ sơ nghiệm thu, hồ sơ quản lý chất lượng; Hồ sơ thanh toán; Hồ sơ quyết toán', NULL, NULL, 'one_time', NULL, NULL, '3'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Kiểm tra, đôn đốc về tiến độ, khối lượng, đơn giá, chất lượng, mỹ thuật/kiến trúc công trình', '6', 'Tổ chức lập, trình xem xét/thẩm định hồ sơ điều chỉnh, bổ sung các vấn đề phát sinh các công trình/dự án do phòng phụ trách quản lý', 'Bao cáo thẩm định, hồ sơ trình', NULL, NULL, 'one_time', NULL, NULL, '4'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Lập Tổ/Nhóm để quản lý  thực hiện công trình/dự án', '7', 'Cập nhật báo cáo về tiến độ thực hiện, khối lượng hoàn thành các hạng mục so với kế hoạch tiến độ đề ra của các công trình/dự án', 'Báo cáo hàng tuần', NULL, NULL, 'one_time', NULL, NULL, '5'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Lập, trình thẩm định đề cương nhiệm vụ tư vấn lập ĐTM; kế hoạch bảo vệ môi trường; kế hoạch, phương án rà phá bom mìn;', '8', 'Chủ trì phối hợp với các đơn vị/địa phương và các tổ chức liên quan để thực hiện công tác giải phóng mặt bằng, tái định cư;', 'Mặt bằn được bàn giao', NULL, NULL, 'one_time', NULL, NULL, '6'),
('2026', 'QLDA1', 'Phòng Quản lý dự án 1', 'Thực hiện công tác báo cáo và trách nhiệm giải trình khi có yêu cầu của cơ quan chức năng  liên quan', '9', 'Rà soát, cập nhật điều chỉnh chế độ chính sách phù hợp; nghiên cứu và áp dụng vào thực tế các sáng kiến kinh nghiệm trong quản lý', 'Báo cáo nội dung cập nhật; Các sáng kiến đề xuất áp dụng', NULL, NULL, 'one_time', NULL, NULL, '7'),
